import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { decryptFile, decryptJson, isEncrypted } from "./crypto.js";
import { loadNcnnFromWasm, materializeWeights } from "./wasmWeights.js";

const defaultCache = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", ".cache");

function exists(p) {
  try {
    return fs.existsSync(p);
  } catch {
    return false;
  }
}

function findFile(dir, names) {
  if (!dir) return null;
  for (const name of names) {
    const p = path.join(dir, name);
    if (exists(p)) return p;
  }
  return null;
}

function naturalSort(a, b) {
  const as = a.split(/(\d+)/);
  const bs = b.split(/(\d+)/);
  const n = Math.max(as.length, bs.length);
  for (let i = 0; i < n; i++) {
    const x = as[i] ?? "";
    const y = bs[i] ?? "";
    const xn = /^\d+$/.test(x);
    const yn = /^\d+$/.test(y);
    if (xn && yn) {
      const d = Number(x) - Number(y);
      if (d) return d;
    } else if (x !== y) {
      return x < y ? -1 : 1;
    }
  }
  return 0;
}

function listFrames(dir) {
  if (!exists(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((f) => /\.(sij|jpg|jpeg|png)$/i.test(f))
    .sort(naturalSort)
    .map((f) => path.join(dir, f));
}

/**
 * bbox.j values are [x1, x2, y1, y2]. Client converts to [x1, y1, x2, y2].
 */
export function parseBbox(data, frameCount) {
  if (!data) return [];
  if (Array.isArray(data)) {
    if (data.length === 4 && data.every((n) => typeof n === "number")) {
      return Array.from({ length: frameCount }, () => data.map((n) => n | 0));
    }
    if (Array.isArray(data[0])) return data;
    return [];
  }
  if (typeof data === "object") {
    if (Array.isArray(data.frames)) return data.frames;
    if (Array.isArray(data.box)) return parseBbox(data.box, frameCount);
    const keys = Object.keys(data).filter((k) => /^\d+$/.test(k));
    keys.sort((a, b) => Number(a) - Number(b));
    return keys.map((k) => {
      const v = data[k];
      if (Array.isArray(v) && v.length === 4) {
        return [v[0] | 0, v[2] | 0, v[1] | 0, v[3] | 0];
      }
      return v;
    });
  }
  return [];
}

function parseBlobIds(idPath) {
  const fallback = { audio: 0, face: 1, output: 180 };
  if (!idPath || !exists(idPath)) return fallback;
  const text = fs.readFileSync(idPath, "utf8");
  const pick = (name, def) => {
    const m = text.match(new RegExp(`BLOB_${name}\\s*=\\s*(-?\\d+)`));
    return m ? Number(m[1]) : def;
  };
  return {
    audio: pick("audio", fallback.audio),
    face: pick("face", fallback.face),
    output: pick("output", fallback.output),
  };
}

function writeCached(cacheDir, name, bytes) {
  fs.mkdirSync(cacheDir, { recursive: true });
  const out = path.join(cacheDir, name);
  fs.writeFileSync(out, bytes);
  return out;
}

/**
 * Resolve shared gj_dh_res + a role directory.
 * Role mouth weights prefer output/<role>/wasm (plaintext ncnn).
 * Frames / bbox / config come from the role directory itself.
 */
export async function loadRoleAssets({ baseDir, roleDir, cacheDir }) {
  if (!exists(baseDir)) throw new Error(`gj_dh_res not found: ${baseDir}`);
  if (!exists(roleDir)) throw new Error(`role dir not found: ${roleDir}`);

  const wenetEnc = findFile(baseDir, ["wenet.o", "wenet.onnx"]);
  if (!wenetEnc) throw new Error(`wenet.o / wenet.onnx missing in ${baseDir}`);
  const maskEnc = findFile(baseDir, ["weight_168u.b", "weight_168u.bin"])
    || findFile(roleDir, ["weight_168u.b", "weight_168u.bin"]);
  if (!maskEnc) throw new Error("weight_168u.b missing");

  const configPath = findFile(roleDir, ["config.j", "config.json"]);
  const bboxPath = findFile(roleDir, ["bbox.j", "bbox.json"]);
  let width = 0;
  let height = 0;
  if (configPath) {
    const cfg = configPath.endsWith(".j") ? decryptJson(configPath) : JSON.parse(fs.readFileSync(configPath, "utf8"));
    width = cfg.width || 0;
    height = cfg.height || 0;
  }

  const rawDir = ["raw_jpgs", "pics", "images", "frames"].map((s) => path.join(roleDir, s)).find(exists) || roleDir;
  const frames = listFrames(rawDir);
  if (!frames.length) throw new Error(`no frames under ${roleDir}`);
  const phaDir = path.join(roleDir, "pha");
  const pha = exists(phaDir) ? listFrames(phaDir) : [];

  let bboxData = null;
  if (bboxPath) {
    bboxData = bboxPath.endsWith(".j") ? decryptJson(bboxPath) : JSON.parse(fs.readFileSync(bboxPath, "utf8"));
  }
  const boxes = parseBbox(bboxData, frames.length);

  const cache = cacheDir || defaultCache;
  let wenetPath = wenetEnc;
  const head = Buffer.alloc(16);
  const fd = fs.openSync(wenetEnc, "r");
  fs.readSync(fd, head, 0, 16, 0);
  fs.closeSync(fd);
  if (wenetEnc.endsWith(".o") || isEncrypted(head)) {
    const cached = path.join(cache, "wenet.onnx");
    const srcStat = fs.statSync(wenetEnc);
    const fresh = exists(cached) && fs.statSync(cached).mtimeMs >= srcStat.mtimeMs && fs.statSync(cached).size > 0;
    if (!fresh) {
      process.stdout.write(`decrypt wenet ${wenetEnc}\n`);
      wenetPath = writeCached(cache, "wenet.onnx", decryptFile(wenetEnc));
    } else {
      wenetPath = cached;
    }
  }

  const maskBytes = maskEnc.endsWith(".b") ? decryptFile(maskEnc) : fs.readFileSync(maskEnc);
  const mask = new Uint8Array(maskBytes.buffer, maskBytes.byteOffset, maskBytes.byteLength);

  const wasmPath = path.join(roleDir, "wasm", "dh_model.wasm");
  let paramPath;
  let binPath;
  let blobs = { audio: 0, face: 1, output: 180 };
  if (exists(wasmPath)) {
    blobs = parseBlobIds(path.join(roleDir, "wasm", "dh_model.id.h"));
    const { paramBin, modelBin } = await loadNcnnFromWasm(wasmPath);
    ({ paramPath, binPath } = materializeWeights(path.join(cache, "wasm"), paramBin, modelBin));
  } else {
    const paramEnc = findFile(roleDir, ["dh_model.param", "dh_model.p"]);
    const binEnc = findFile(roleDir, ["dh_model.bin", "dh_model.b"]);
    if (!paramEnc || !binEnc) throw new Error("role mouth model missing (wasm or dh_model.p/.b)");
    paramPath = paramEnc.endsWith(".p")
      ? writeCached(cache, "dh_model.param", decryptFile(paramEnc))
      : paramEnc;
    binPath = binEnc.endsWith(".b")
      ? writeCached(cache, "dh_model.bin", decryptFile(binEnc))
      : binEnc;
  }

  return {
    width,
    height,
    wenetPath,
    paramPath,
    binPath,
    blobs,
    mask,
    frames,
    pha,
    boxes,
  };
}
